create_navbar <- function() {
  div(
    class = "custom-navbar",
    a("Landing", href = "#landing", class = "nav-item"),
    a("Definitions", href = "#definitions-gs", class = "nav-item"),
    a("Foundations", href = "#foundations", class = "nav-item"),
